codeExample:
ARG VERSION=dev
FROM app:${VERSION}
RUN echo "built ${VERSION}" > /etc/app-version

selector:
  matchLabels: {app.kubernetes.io/name: api}
  matchExpressions:
  - {key: tier, operator: In, values: [backend]}

for {
  desired := spec.Load
  actual := client.Get()
  if actual != desired { client.Scale(desired) }
  select {
  case <-queue: case <-time.After(30*time.Second):
  }
}

func (c *Ctrl) Reconcile(ctx context.Context, req ctrl.Request) (ctrl.Result, error) {
  if err := c.apply(ctx, req); err != nil { return ctrl.Result{}, err }
  return ctrl.Result{RequeueAfter: 30 * time.Second}, nil
}

admissionReview:
  request:
    object: {metadata: {labels: {pinned: "true"}}}
  response:
    allowed: false
    status: {message: "digest pinning required"}

kind: RoleBinding
metadata: {name: api-reader, namespace: payments}
roleRef: {apiGroup: rbac.authorization.k8s.io, kind: Role, name: api-reader}
subjects: [{kind: ServiceAccount, name: api, namespace: payments}]

kind: ClusterRole
metadata: {name: node-reader}
rules: [{apiGroups: [""], resources: ["nodes"], verbs: ["get","list"]}]

kind: LimitRange
spec:
  limits:
  - type: Container
    default: {cpu: 500m, memory: 512Mi}
    defaultRequest: {cpu: 100m, memory: 128Mi}

updateMode: Auto
resourcePolicy:
  containerPolicies:
  - containerName: api
    minAllowed: {cpu: 250m, memory: 512Mi}
    maxAllowed: {cpu: "4", memory: 8Gi}

http:
  routes:
  - match: {path: /}
    backend: {service: {name: api-v2, port: 8080}}
    weight: 5

containers:
- name: api
  ports:
  - {name: http, containerPort: 8080, protocol: TCP}
  readinessProbe:
    httpGet: {path: /readyz, port: http}

kind: PersistentVolumeClaim
metadata: {name: data}
spec:
  accessModes: [ReadWriteOnce]
  resources: {requests: {storage: 100Gi}}
  storageClassName: ebs-sc

kind: StorageClass
metadata: {name: fast-ssd}
provisioner: ebs.csi.aws.com
parameters: {type: gp3}
reclaimPolicy: Delete
volumeBindingMode: WaitForFirstConsumer

volumes:
- name: bundle
  projected:
    sources:
    - configMap: {name: app-config}
    - secret: {name: app-secret}
    - downwardAPI: {items: [{path: labels, fieldRef: {fieldPath: metadata.labels}}]}

env:
- name: POD_IP
  valueFrom: {fieldRef: {fieldPath: status.podIP}}
- name: POD_NAME
  valueFrom: {fieldRef: {fieldPath: metadata.name}}

kind: RuntimeClass
metadata: {name: gvisor}
handler: runsc
spec:
  overhead: {podFixed: 128Mi}

panels:
  - title: p99 latency
    query: p99_latency_seconds{service="api"}
